    private interface Tx<T>{T run()throws Exception;}
    private int txDepth;
    private synchronized <T>T tx(Tx<T> task){if(txDepth>0){try{return task.run();}catch(IdentityException e){throw e;}catch(Exception e){throw new IllegalStateException("Identity storage failure",e);}}try(Statement s=db.createStatement()){s.execute("BEGIN IMMEDIATE");txDepth++;try{T value=task.run();s.execute("COMMIT");return value;}catch(Exception e){s.execute("ROLLBACK");if(e instanceof IdentityException failure)throw failure;if(e instanceof IllegalArgumentException failure)throw failure;throw new IllegalStateException("Identity storage failure",e);}finally{txDepth--;}}catch(SQLException e){throw new IllegalStateException("Identity storage unavailable",e);}}
    private static void deny(){throw new IdentityException("DENIED");}
    private void execute(String sql,Object... values)throws SQLException {try(PreparedStatement p=db.prepareStatement(sql)){bind(p,values);p.executeUpdate();}}
    private static void bind(PreparedStatement p,Object... values)throws SQLException {for(int i=0;i<values.length;i++)p.setObject(i+1,values[i]);}
    private boolean exists(String sql,Object... values)throws SQLException {try(PreparedStatement p=db.prepareStatement(sql)){bind(p,values);try(ResultSet r=p.executeQuery()){return r.next();}}}
    private long number(String sql,Object... values)throws SQLException {try(PreparedStatement p=db.prepareStatement(sql)){bind(p,values);try(ResultSet r=p.executeQuery()){if(!r.next())deny();return r.getLong(1);}}}
    private String text(String sql,Object... values)throws SQLException {try(PreparedStatement p=db.prepareStatement(sql)){bind(p,values);try(ResultSet r=p.executeQuery()){if(!r.next())deny();return r.getString(1);}}}
    private byte[] blob(String sql,Object... values)throws SQLException {try(PreparedStatement p=db.prepareStatement(sql)){bind(p,values);try(ResultSet r=p.executeQuery()){if(!r.next())deny();return r.getBytes(1);}}}
    private void limit(String sql,int max)throws SQLException {if(number(sql)>=max)throw new IdentityException("LIMIT");}
    private void limitFor(String sql,String account,int max)throws SQLException {if(number(sql,account)>=max)throw new IdentityException("LIMIT");}
    @Override public synchronized void close()throws SQLException {Arrays.fill(auditKey,(byte)0);db.close();}
